-- MySQL automatically creates the supporting FK index if it is absent.
-- These guards make the index names explicit and safe to rerun after constraints.
USE `smartagriculturedb`;
SET @schema_name = DATABASE();

SET @ddl = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='advisory' AND INDEX_NAME='Pest_ID')=0,'CREATE INDEX `Pest_ID` ON `advisory` (`Pest_ID`)','SELECT ''advisory.Pest_ID exists'' AS status'); PREPARE fieldwise_stmt FROM @ddl; EXECUTE fieldwise_stmt; DEALLOCATE PREPARE fieldwise_stmt;
